from pathlib import Path
from html import escape as e
import re
R=Path(__file__).parent

def table(caption,heads,rows):
 return '<div class="table-wrap"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,title,paragraphs,extra=''):
 return f'<section id="{id}"><h2>{title}</h2>'+''.join('<p>'+p+'</p>' for p in paragraphs)+extra+'</section>'
D={}
D['dakwerken']=[
section('richtprijzen','Dakwerken prijs per m²: welke budgetten kun je vergelijken?',[
'Voor een eerste budget is het nuttig om onderscheid te maken tussen nieuwe dakbedekking en een volledige dakrenovatie. Onderstaande bedragen zijn gepubliceerde indicaties van dakrenovatiespecialist Kijzer, geraadpleegd op 14 oktober 2026. Ze zijn exclusief btw en gelden niet als offerte van Mijnenergie of Testinstallateur.',
'De breedte van een prijsrange zegt iets over de variatie tussen werven. Een eenvoudig, bereikbaar dak met een gezonde draagstructuur vraagt andere werken dan een dak met moeilijke aansluitingen of verborgen schade. Vraag daarom welke opbouw de aanbieder in de prijs per vierkante meter heeft opgenomen.'],table('Gepubliceerde budgetindicaties voor dakrenovatie',['Werkzaamheden','Indicatie excl. btw','Vergelijkingspunt'],[
['Bedekking vernieuwen','€70–€150/m²','Overige opbouw blijft behouden'],['Hellend dak met isolatie','€180–€280/m²','Volledige standaardrenovatie'],['Plat dak met isolatie','€130–€220/m²','Opbouw en afdichting'],['Complexe renovatie','€250–€400+/m²','Maatwerk of bijkomende ingrepen']])+'<p class="small">Bron: <a href="https://www.kijzer.be/inspiratie/wat-kost-de-renovatie-van-je-dak/">Kijzer: dakrenovatieprijzen</a>. Materialen, uitvoering en inbegrepen posten moeten per offerte worden bevestigd.</p>'),
section('budgetvoorbeeld','Wat kost een nieuw dak van 100 m²?',[
'Een rekenvoorbeeld maakt de schaal van de investering duidelijker. Neem een hellend dak met 100 m² werkelijk te behandelen dakoppervlak. Met de hierboven vermelde bandbreedte van €180 tot €280 per m² bedraagt de rekenkundige indicatie €18.000 tot €28.000 exclusief btw. Dit voorbeeld is afgeleid van de bronrange, niet van een inspectie van een woning.',
'De oppervlakte van je woning is niet hetzelfde als de dakoppervlakte. Laat die correct meten. Bereken bovendien niet alleen de zichtbare vlakken: aansluitingen, dakramen en afwerking kunnen de opdracht beïnvloeden. Vraag bij een totaalbudget apart naar eventuele structurele herstellingen en naar de aanpak van onverwachte schade.',
'Werk voor je eigen planning met een basisofferte en een lijst van mogelijke bijkomende posten. Leg vast welke posten vast geprijsd zijn en welke na onderzoek worden bepaald. Dat is bruikbaarder dan zonder uitleg een algemeen percentage boven op elke online richtprijs te zetten. Btw, premies en financiering behandel je afzonderlijk.']),
section('materiaalvergelijking','Dakpannen, leien, EPDM of bitumen: hoe kies je?',[
'Begin bij de dakvorm en de technische geschiktheid. Een materiaal dat er mooi uitziet, is pas een goede optie als de dakhelling, draagkracht en aansluitingen erbij passen. Bespreek eerst welke oplossingen mogelijk zijn en vergelijk daarna uitvoering en budget.',
'Vraag geen materiaalkeuze op basis van één beloofde levensduur. Productkwaliteit, plaatsing, onderhoud en details hebben invloed op de prestaties. Laat bij elke voorgestelde bedekking uitleggen hoe een plaatselijke herstelling gebeurt en welke documentatie of garanties je ontvangt.'],table('Materialen vergelijken zonder verschillende daktypes door elkaar te halen',['Materiaal','Toepassing','Vraag aan de dakwerker'],[['Dakpannen','Geschikt hellend dak','Welk gewicht en welke minimale helling?'],['Leien','Geschikt hellend dak','Welk type, welke bevestiging en welk onderdak?'],['EPDM','Geschikt plat dak','Hoe worden naden en aansluitingen uitgevoerd?'],['Bitumen','Geschikt plat dak','Welke laagopbouw en afwerking zijn voorzien?']])),
section('isolatiekeuze','Dakisolatie langs binnen of buiten: wat past bij jouw renovatie?',[
'Bij isolatie langs binnen blijft de buitenste bedekking in bepaalde situaties behouden. De binnenafwerking en beschikbare ruimte spelen dan mee in de keuze. Vraag hoe de uitvoerder de bestaande daklagen beoordeelt en hoe de nieuwe isolatie aansluit op muren, ramen en andere bouwdelen.',
'Bij een renovatie waarbij de bedekking toch verwijderd wordt, kun je ook isolatie langs buiten bespreken. Laat de offerte dan het volledige pakket beschrijven, zodat je geen losse isolatieprijs vergelijkt met een prijs inclusief bedekking, afbraak en afwerking. De plaatsing rond dakdetails verdient evenveel aandacht als het isolatiemateriaal zelf.',
'Vraag naar de warmteweerstand en naar de samenhang tussen isolatie, vochtbeheersing en luchtdichting. Een merknaam of dikte alleen geeft onvoldoende informatie. Laat onduidelijkheid over vochtplekken onderzoeken voordat je bestaande lagen afsluit. Bij een ingewikkelde dakopbouw kan technisch advies nodig zijn.']),
section('premieoverzicht','Dakpremies in Vlaanderen: welke situatie geldt in 2026?',[
'Voor Mijn VerbouwPremie is de aanvraagdatum belangrijk. Voor eigenaar-bewoners in inkomenscategorie 1 en 2 vermeldt Vlaanderen vanaf 1 maart 2026 geen dakpremie meer. Voor categorie 3 en 4 gelden andere voorwaarden en bedragen. Voor gemeenschappelijke delen van appartementsgebouwen bestaat een afzonderlijk regime.',
'Controleer je categorie, gebouwvoorwaarden, vereiste isolatie en facturen vóór je een premie in je budget aftrekt. Een online prijsberekening kan je recht op steun niet vaststellen. Gebruik de officiële regeling voor jouw situatie; onderstaande tabel is alleen een wegwijzer voor particuliere woningen.'],table('Mijn VerbouwPremie voor dak: samenvatting aanvragen vanaf 1 maart 2026',['Situatie','Gepubliceerd bedrag','Let op'],[['Categorie 4 / verhuur aan woonmaatschappij','50%, maximaal €5.750','Alle voorwaarden en subsidiabele posten'],['Categorie 3','35%, maximaal €4.025','Alle voorwaarden en subsidiabele posten'],['Categorie 1 en 2','Geen dakpremie','Voor aanvragen vanaf 1 maart 2026'],['Gemeenschappelijke appartementsdelen','Afzonderlijke regeling','Controleer de officiële pagina']])+'<p class="small">Bron en volledige voorwaarden: <a href="https://www.vlaanderen.be/bouwen-wonen-en-energie/bouwen-en-verbouwen/premies-voor-renovatie/mijn-verbouwpremie/mijn-verbouwpremie-voor-dak">Vlaanderen: Mijn VerbouwPremie voor dak</a>. Eventuele asbesttoeslagen zijn niet in deze samenvatting verwerkt.</p>'),
section('onderhoud','Onderhoud, vochtproblemen en voorbereiding van de werf',[
'Noteer zichtbare problemen en wanneer ze optreden. Een vochtplek na slagregen kan een andere aanleiding hebben dan condensatie die vooral in een koude periode verschijnt. Maak foto’s vanaf een veilige plaats en geef die aan de dakwerker. Klim niet zelf op het dak om een vermoeden te bevestigen.',
'Bespreek hoe de woning tijdens de werken wordt beschermd en welke toegang nodig is voor materiaal en afvoer. Vraag wie de werfzone organiseert en hoe de uitvoerder omgaat met slecht weer. Leg ook vast welke delen binnenshuis bereikbaar moeten blijven en of afwerking na de dakwerken deel uitmaakt van de opdracht.',
'Bij oplevering loop je de afgesproken posten na: afwerking, goten, afvoer, dakramen en aansluitingen. Vraag onderhoudsinstructies en de product- en garantiedocumenten. Bewaar de offerte samen met de eindfactuur. Zo is later zichtbaar wat daadwerkelijk is vernieuwd en waar je terechtkunt voor nazorg.'])]
D['zonnepanelen']=[
section('prijsvoorbeelden','Zonnepanelen prijs: voorbeelden van complete installaties',[
'Een prijs per paneel zegt weinig zonder omvormer, montage en elektrische werken. Onderstaande voorbeelden komen uit het openbare aanbod van Luminus, geraadpleegd op 14 oktober 2026. Het zijn aanbiedersvoorbeelden, geen onafhankelijk marktgemiddelde of offerte voor jouw dak.',
'In de bron staan panelen van 465 Wp, een hybride omvormer, plaatsing, keuring en monitoring bij de voorbeelden. Het vermogen in kWp hieronder is berekend uit het aantal panelen. De publieke prijspresentatie specificeert op deze pagina de btw-basis niet; laat die en de exacte inbegrepen werken in je offerte bevestigen.'],table('Gepubliceerde installatievoorbeelden van Luminus',['Aantal panelen','Berekend vermogen','Gepubliceerde prijs'],[['6 × 465 Wp','2,79 kWp','€4.300'],['8 × 465 Wp','3,72 kWp','€4.700'],['16 × 465 Wp','7,44 kWp','€6.400']])+'<p class="small">Bron: <a href="https://www.luminus.be/nl/prive/energieoplossingen/zonnepanelen/">Luminus: zonnepanelen</a>. Prijzen en aanbod kunnen veranderen. Eventuele dak- of kastaanpassingen moeten afzonderlijk worden nagekeken.</p>'),
section('offerteposten','Welke kosten moeten op de zonnepanelenofferte staan?',[
'Vraag een uitgesplitste werkomschrijving. Panelen en omvormer zijn herkenbare onderdelen, maar montagemateriaal, bekabeling, veiligheid en aansluiting bepalen mee wat geleverd wordt. Een goedkoop voorstel kan een andere opdracht omvatten dan een offerte met aanpassingen aan de elektriciteitskast.',
'Bespreek ook de route van kabels en de plaats van de omvormer. Die keuzes beïnvloeden uitvoering en toegankelijkheid. Laat uitleggen of er bijkomend werk nodig is aan je dak of elektrische installatie. Vraag hoe zulke posten worden geprijsd en wie ze uitvoert.',
'Controleer welke ondersteuning na plaatsing inbegrepen is. Alleen toegang tot een app betekent niet dat iemand afwijkingen actief opvolgt. Leg vast wie een storing behandelt, hoe je die meldt en welke documenten bij oplevering beschikbaar zijn.'],table('Checklist voor een vergelijkbare totaalprijs',['Post','Laat bevestigen'],[['Panelen en omvormer','Merk, model, aantallen en vermogen'],['Montage en kabels','Dakbevestiging, kabelroute en afwerking'],['Elektrische werken','Aansluiting en eventuele kastaanpassingen'],['Oplevering','Keuring, registratieafspraken en monitoring'],['Nazorg','Garantie, aanspreekpunt en eventuele kosten']])),
section('opbrengstrekenen','Opbrengst en rendement: hoe lees je een berekening?',[
'Het piekvermogen van je panelen is geen voorspelling van hun jaarlijkse productie. Vraag naar een berekening voor jouw adres en legplan, met de oriëntatie, helling en schaduw die werkelijk aanwezig zijn. Een vergelijking tussen twee voorstellen werkt alleen als dezelfde woning en uitgangspunten gebruikt worden.',
'Een fictief voorbeeld: bij 4.000 kWh jaarlijkse productie en 30% rechtstreeks eigen gebruik verbruik je 1.200 kWh zonnestroom zelf. Bij 45% is dat 1.800 kWh. Het verschil is 600 kWh. Welke geldwaarde dat heeft, hangt af van de vermeden aankoopkosten en de injectievergoeding. Deze percentages zijn gekozen om de berekening te tonen, niet als voorspelling voor een gemiddeld gezin.',
'Vraag zowel naar productie als naar eigen gebruik. Een hoge opbrengst kan samengaan met veel injectie als je vooral op andere momenten stroom gebruikt. Leg mogelijke veranderingen in het verbruik apart vast, zodat een optimistische toekomstverwachting niet ongemerkt als huidige situatie in de simulatie terechtkomt.']),
section('terugverdientijd','Terugverdientijd berekenen zonder een gegarandeerde besparing te beloven',[
'Een eenvoudige terugverdientijd deelt de investering door een veronderstelde jaarlijkse netto besparing. Neem uitsluitend als rekenvoorbeeld €5.000 investering en €500 netto besparing per jaar: dat geeft tien jaar. Deze rekensom houdt niet automatisch rekening met financiering, toekomstige vervanging of veranderende tarieven.',
'Vraag voor je beslissing ten minste een voorzichtiger scenario naast de hoofdvariant. Wat gebeurt er als het eigen gebruik lager is, de injectievergoeding verandert of een extra kost nodig blijkt? De invloed van elke aanname is nuttiger dan één exact ogend aantal jaren.',
'Beoordeel de investering bovendien samen met de levensduur van de onderdelen en de garantievoorwaarden. Leg periodieke kosten en mogelijke vervanging apart vast. Gebruik de calculator als voorbereiding, en laat de definitieve berekening onderbouwen met jouw dakgegevens en verbruik.']),
section('dakopstellingen','Zuid, oost-west of plat dak: verschillende legplannen vergelijken',[
'Een geschikt legplan hoeft niet voor elke woning dezelfde richting en indeling te hebben. Vraag waarom de aanbieder de gekozen opstelling voorstelt en wat die betekent voor het productieprofiel. Het doel is een onderbouwde keuze voor jouw dak, niet de grootste hoeveelheid panelen zonder verdere uitleg.',
'Op een plat dak moeten ook afwatering, onderhoudsroutes en de bestaande constructie in het plan zichtbaar blijven. Bij een hellend dak zijn bevestiging, dakramen, schoorstenen en bereikbaarheid belangrijke gesprekspunten. Laat vastleggen welke dakdelen niet bruikbaar zijn en waarom.',
'Vergelijk bij schaduwproblemen de voorgestelde oplossing en de extra investering. Vraag welke prestatie het specifieke ontwerp verwacht en welke aannames zijn gebruikt. Een extra technisch onderdeel is niet zonder meer nodig op elke woning.'],table('Vragen bij het legplan',['Onderdeel','Vergelijkingsvraag'],[['Oriëntatie','Wanneer verwacht je productie op dit dak?'],['Schaduw','Welke obstakels zijn meegenomen in de simulatie?'],['Constructie','Hoe is de geschiktheid van het dak vastgesteld?'],['Onderhoud','Blijven afvoer en relevante dakdelen bereikbaar?'],['Toekomst','Welke concrete uitbreiding is technisch voorzien?']])),
section('onderhoudgarantie','Onderhoud, monitoring en garanties na de plaatsing',[
'Gebruik de monitoring om patronen te leren kennen. Vergelijk niet één bewolkte dag met een zonnige dag om een storing te beoordelen. Noteer foutmeldingen en bespreek afwijkingen met je installateur. Vraag welke controle je zelf veilig kunt uitvoeren en wat een vakman moet nakijken.',
'Laat productgarantie, eventuele vermogensgarantie en garantie op plaatsing afzonderlijk uitleggen. Ze beantwoorden verschillende vragen en kunnen andere voorwaarden hebben. Vraag wie een claim afhandelt en of onderzoek, arbeid, vervoer en vervanging onder dezelfde afspraak vallen.',
'Bewaar legplan, modellen, serienummers en keuringsdocumenten op één plek. Leg ook vast wie de registratie regelt en of je toegang tot de monitoring behouden blijft bij een leverancierswissel. Controleer actuele procedures bij de netbeheerder; financiering en steunregelingen beoordeel je voor het gewest waarin de woning ligt.'])]
D['thuisbatterij']=[
section('prijsvoorbeelden','Thuisbatterij prijs: waarom verschillen offertes zo sterk?',[
'Het batterijpakket alleen is niet de volledige investering. Omvormer, plaatsing, elektrische aanpassingen en software kunnen mee op de offerte staan. ENGIE publiceert illustratieve voorbeelden van €6.000 tot €9.000 voor het toevoegen van een batterij bij bestaande zonnepanelen. Dezelfde pagina noemt ook een algemene bandbreedte van €4.000 tot €8.000, afhankelijk van systeem en installatie.',
'Dat zijn verschillende beschrijvingen, geen vaste prijslijst die je zonder meer per capaciteit kunt toepassen. De publieke voorbeelden geven geen uniforme btw-basis en volledige werkomschrijving. Laat beide bevestigen. We nemen daarom geen schijnbaar exacte prijstabel per kWh over zonder een vergelijkbare, gespecificeerde installatie.'],table('Gepubliceerde voorbeelden: vergelijk de scope',['Voorbeeld van ENGIE','Gepubliceerde indicatie','Interpretatie'],[['Algemene batterij-indicatie','€4.000–€8.000','Afhankelijk van systeem en installatie'],['Toevoegen bij bestaande zonnepanelen','€6.000–€9.000','Illustratief installatievoorbeeld']])+'<p class="small">Bron: <a href="https://www.engie.be/nl/thuisbatterij/">ENGIE: thuisbatterij</a>, geraadpleegd 14 oktober 2026. Geen offerte, geen marktgemiddelde; btw en inbegrepen posten navragen.</p>'),
section('kostentabel','Wat hoort in het volledige batterijbudget?',[
'Vraag eerst welke apparatuur behouden blijft. Bij een uitbreiding kan een bestaande omvormer bruikbaar zijn of een andere aansluitoplossing nodig blijken. Laat de installateur de keuze toelichten voordat je twee totaalbedragen vergelijkt. Een systeem dat tegelijk met een nieuwe installatie wordt geplaatst, is een andere opdracht dan een uitbreiding van een bestaande woning.',
'Breng eenmalige en terugkerende kosten afzonderlijk in kaart. Een abonnement kan bij bepaalde functies horen, terwijl andere functies zonder abonnement werken. Vraag wat er gebeurt wanneer je het abonnement beëindigt, van leverancier verandert of tijdelijk geen internet hebt.',
'Noodstroom kan extra onderdelen en werkzaamheden vragen. Laat die optie apart omschrijven en prijzen als ze voor jou belangrijk is. Vraag welke kringen ondersteund worden; “backup” zonder technische invulling is geen voldoende duidelijke bestelling.'],table('Offerteposten voor een thuisbatterij',['Post','Vergelijk op'],[['Batterijmodules','Model en bruikbare capaciteit'],['Omvormer / integratie','Behouden of aanpassen van bestaande apparatuur'],['Plaatsing en elektrische werken','Concrete inbegrepen werkzaamheden'],['Sturing','Functies, afhankelijkheden en abonnement'],['Noodstroom','Ondersteunde kringen en extra onderdelen'],['Oplevering en nazorg','Documentatie, keuring en garantiekosten']])),
section('capaciteitsvergelijking','5, 10 of 15 kWh: welke capaciteit heeft zin?',[
'Gebruik capaciteit als vergelijking, niet als automatisch aankoopadvies. Een kleinere batterij kan bij een beperkt beschikbaar overschot voldoende zijn; een groter systeem vraagt voldoende laadmogelijkheden en later verbruik. Jaarverbruik alleen vertelt niet wanneer de stroom beschikbaar is.',
'Vraag een vergelijking met dezelfde verbruiksgegevens voor meerdere capaciteiten. Hoe vaak wordt elk systeem daadwerkelijk gebruikt, en welk bijkomend voordeel geeft de volgende maat? Zet de meerprijs naast die extra benutting. Kijk ook naar de bruikbare capaciteit in plaats van alleen naar het getal in de productnaam.',
'Een eenvoudig energievoorbeeld: 5 kWh bruikbare energie kan rekenkundig vijf uur lang 1 kW leveren vóór bijkomende verliezen of systeembeperkingen. Het zegt niet of de batterij een zwaar toestel kan starten of meerdere toestellen tegelijk ondersteunt. Daarvoor zijn onder meer het vermogen en de elektrische configuratie van belang.'],table('Capaciteiten als onderzoeksscenario, geen maatadvies',['Scenario','Wat laat je berekenen?'],[['5 kWh','Benutting bij je normale dag- en avondverbruik'],['10 kWh','Extra bruikbare opslag tegenover de kleinere variant'],['15 kWh','Of voldoende overschot en later verbruik aanwezig zijn'],['Uitbreidbaar systeem','Kosten en voorwaarden van latere modules']])),
section('besparingsvoorbeeld','Besparing en terugverdientijd: een transparant rekenvoorbeeld',[
'Een batterij verschuift stroom tussen momenten. Bij gebruik van een zonneoverschot vergelijk je de waarde van later vermeden aankoop met de injectieopbrengst die je opgeeft en de opslagverliezen. De financiële uitkomst verandert wanneer tarieven of gebruik veranderen.',
'Neem een fictief voorbeeld, uitsluitend om het principe te tonen: 1.500 kWh wordt jaarlijks geladen uit een overschot dat anders zou worden geïnjecteerd. Bij een aangenomen rendement van 90% komt 1.350 kWh terug beschikbaar. Met gekozen waarden van €0,30 vermeden aankoop en €0,05 gemiste injectie is het verschil €405 min €75, of €330 per jaar vóór andere kosten. Dit zijn geen actuele tariefgegevens of voorspelde prestaties.',
'Bij een fictieve investering van €6.000 geeft €330 jaarlijkse besparing ongeveer achttien jaar eenvoudige terugverdientijd. Dat voorbeeld houdt geen rekening met abonnement, financiering, slijtage of vervanging. Andere aannames geven een andere uitkomst. Het toont waarom je een batterij niet uitsluitend op een aantrekkelijke opbrengstbelofte moet beoordelen.']),
section('sturingsvergelijking','Eigen verbruik, pieken en dynamische sturing vergelijken',[
'Vraag welk doel de sturing nastreeft en hoe de aanbieder dat meet. Meer eigen zonnestroom gebruiken, verbruikspieken beïnvloeden en reageren op veranderende elektriciteitsprijzen zijn verschillende toepassingen. De mogelijkheid en het voordeel hangen af van het systeem, je contract en je verbruik.',
'Laat de berekening duidelijk maken of voordelen elkaar overlappen. Dezelfde opgeslagen energie kan niet zonder uitleg als volledig voordeel in meerdere afzonderlijke besparingsposten worden geteld. Vraag naar een totaalberekening waarin ook verliezen en terugkerende kosten zitten.',
'Bespreek welke invloed je zelf hebt op de instellingen en welke reserve voor eventueel noodstroomgebruik behouden blijft. Een hoge reserve betekent dat niet alle opslag beschikbaar is voor ander gebruik. Laat voor jouw prioriteiten een passende instelling voorstellen.'],table('Doelen van sturing',['Doel','Vraag bij de simulatie'],[['Eigen zonnestroom gebruiken','Hoeveel extra energie wordt later benut?'],['Verbruikspieken beïnvloeden','Welke pieken zijn gemeten en haalbaar te beperken?'],['Reageren op dynamische prijzen','Welk contract, welke kosten en welke scenario’s?'],['Noodstroomreserve','Welke capaciteit blijft gereserveerd?']])),
section('garantievergelijking','Levensduur, garantie en veiligheid: wat leg je vast?',[
'Een garantietermijn zegt niet alles. Vraag welke restcapaciteit eventueel wordt gegarandeerd, welke gebruiksvoorwaarden gelden en of een beperking op energie-doorvoer of cycli van toepassing is. Vraag bij onduidelijke termen om een voorbeeld voor jouw verwachte gebruik.',
'Laat productgarantie en installatiegarantie afzonderlijk beschrijven. Controleer wie diagnose en vervanging organiseert en welke kosten daarin passen. Een afspraak over een vervangend onderdeel is niet automatisch een afspraak over arbeid, vervoer en de bereikbaarheid van de installatie.',
'Vraag om een plaatsingsvoorstel volgens de voorschriften van het gekozen product. Temperatuur, toegang, bescherming en de bestaande elektrische installatie moeten daarin worden meegenomen. Bespreek onderhoud en wat je bij foutmeldingen moet doen. Premies, registratie en eventuele fiscale voorwaarden controleer je bij de bevoegde overheid of netbeheerder voor jouw situatie; reken geen onbevestigde steun mee.'])]
for sector,parts in D.items():
 p=R/f'{sector}-info/index.html';s=p.read_text()
 if 'id="seo-uitbreiding"' in s:continue
 # Put price information before the calculator and retain all existing visual breaks.
 block='<div id="seo-uitbreiding">'+''.join(parts)+'</div>'
 s=s.replace('<section id="calculator"',block+'<section id="calculator"',1)
 titles=re.findall(r'<section id="([^"]+)"><h2>(.*?)</h2>',block)
 toc=''.join(f'<li><a href="#{id}">{title}</a></li>' for id,title in titles)
 s=s.replace('<li><a href="#calculator">',toc+'<li><a href="#calculator">',1)
 s=s.replace('13 oktober 2026','14 oktober 2026')
 s=s.replace('Informatieve conceptgids','Uitgebreide conceptgids')
 p.write_text(s)
 print(sector,len(re.sub('<[^>]+>',' ',s).split()),'woorden incl. navigatie')
